<script setup>
import {ref,onMounted} from 'vue';import {get} from '../services/api.js';const logs=ref([]),health=ref(null),error=ref('');onMounted(async()=>{try{logs.value=await get('/audit');health.value=await get('/health')}catch(e){error.value=e.message}})
</script>
<template><div class="page"><div class="top"><div><div class="eyebrow">TEACHER · TRUST + CONTROL</div><div class="h1">Governance</div><p class="muted">The teacher remains responsible for classroom decisions. The system supports evidence, recommendations and traceability.</p></div></div><div class="grid grid3"><div class="card"><div class="icon">01</div><h3>Role-based access</h3><p class="muted">Teacher-facing views contain detailed learner information. Aggregated views are used for school and system reporting.</p></div><div class="card"><div class="icon">02</div><h3>Bounded AI</h3><p class="muted">AI can rank approved activities, summarize changes and flag persistent patterns. It does not grade autonomously or make high-stakes decisions.</p></div><div class="card"><div class="icon">03</div><h3>Audit trail</h3><p class="muted">Assessment, intervention and reassessment actions create traceable events for review.</p></div></div><div class="card" style="margin-top:16px"><div class="top"><div><div class="eyebrow">SYSTEM STATUS</div><h2>Classroom workflow health</h2></div><div><span class="pill success">{{health?.ok?'API online':'Checking'}}</span> <span class="pill">{{health?.mode||'demo'}}</span></div></div><h3 style="margin-top:24px">Recent activity</h3><div v-if="logs.length"><div v-for="l in logs" :key="l.id" class="log"><div><strong>{{l.action}}</strong><p class="muted">{{l.detail}}</p></div><small class="muted">{{new Date(l.at).toLocaleString()}}</small></div></div><p v-else class="muted">No audit events yet. Complete an assessment or intervention to create one.</p></div><div class="card" style="margin-top:16px"><h2>Offline-first principle</h2><p class="muted">Core classroom work should remain usable without continuous internet; synchronization can happen when connectivity returns.</p></div></div></template><style scoped>.icon{font-weight:800;font-size:12px}.log{display:flex;justify-content:space-between;gap:20px;border-top:1px solid #e2e8f0;padding:12px 0}.log p{margin:4px 0}</style>